from __future__ import annotations

"""Case-insensitive lookup for protocol and identifier tokens.

The serving stack treats a handful of token namespaces case-insensitively:
feature-flag keys, HTTP header names, and locale/country codes all need
``"X-Request-Id"`` and ``"x-request-id"`` to resolve to the same entry, and
``"NewCheckout"`` and ``"newcheckout"`` to point at the same flag.

The registry stores each token under a folded key and folds lookup keys the same
way before comparing. Folding is done through :mod:`case_fold`. The process
reports its locale through :func:`current_locale`, which reads ``LC_CTYPE`` /
``LANG`` from the environment so the same image can run in different regions.
"""

import os

from case_fold import fold_invariant, fold_locale


def current_locale() -> str:
    """Return the locale the process is running under.

    Falls back through the usual environment variables and finally to ``"en"``
    when nothing is set. Region pods set this to whatever their deployment
    region uses (for example ``tr_TR.UTF-8`` for the Turkey region).
    """

    for var in ("LC_ALL", "LC_CTYPE", "LANG"):
        value = os.environ.get(var)
        if value:
            return value
    return "en"


def normalize_token(token: str, locale: str | None = None) -> str:
    """Fold a single token to its canonical comparison key.

    ``locale`` is accepted so callers can normalize for a specific request
    context; when omitted it uses the process locale.
    """

    loc = locale if locale is not None else current_locale()
    return fold_locale(token, loc)


class TokenRegistry:
    """A case-insensitive map from token -> value.

    Keys are stored folded so that any case variant of the same token resolves
    to one entry. Iteration preserves insertion order of the original tokens.
    """

    def __init__(self) -> None:
        self._by_key: dict[str, object] = {}
        self._display: dict[str, str] = {}
        self._order: list[str] = []

    def _key(self, token: str) -> str:
        # Fold against the locale this process is running under.
        return fold_locale(token, current_locale())

    def register(self, token: str, value: object) -> None:
        if not isinstance(token, str):
            raise TypeError("token must be a string")
        key = self._key(token)
        if key not in self._by_key:
            self._order.append(key)
        self._by_key[key] = value
        self._display[key] = token

    def contains(self, token: str) -> bool:
        return self._key(token) in self._by_key

    def get(self, token: str, default: object = None) -> object:
        return self._by_key.get(self._key(token), default)

    def display_name(self, token: str) -> str | None:
        return self._display.get(self._key(token))

    def tokens(self) -> list[str]:
        return [self._display[key] for key in self._order]

    def __len__(self) -> int:
        return len(self._by_key)


def tokens_match(left: str, right: str) -> bool:
    """True when two tokens are the same under case-insensitive matching.

    Used to compare an incoming HTTP header name against a configured one, or a
    requested flag key against a registered one.
    """

    return fold_locale(left, current_locale()) == fold_locale(right, current_locale())


class HeaderTable:
    """Case-insensitive HTTP header store built on the same matching rules."""

    def __init__(self) -> None:
        self._registry = TokenRegistry()

    def set(self, name: str, value: str) -> None:
        self._registry.register(name, value)

    def get(self, name: str, default: str | None = None) -> str | None:
        result = self._registry.get(name, default)
        return result if result is None else str(result)

    def has(self, name: str) -> bool:
        return self._registry.contains(name)

    def names(self) -> list[str]:
        return self._registry.tokens()


def build_flag_registry(flags: dict[str, bool]) -> TokenRegistry:
    """Build a feature-flag registry from a ``{key: enabled}`` mapping."""

    registry = TokenRegistry()
    for key, enabled in flags.items():
        registry.register(key, bool(enabled))
    return registry


def is_flag_enabled(registry: TokenRegistry, key: str) -> bool:
    """Return whether ``key`` is registered and enabled."""

    return bool(registry.get(key, False))

